import json
from copy import deepcopy

def solve():
    houses = range(1, 7)

    CATEGORIES = ["Name", "HouseStyle", "MusicGenre", "Hobby"]

    Names = ["Eric", "Alice", "Arnold", "Carol", "Peter", "Bob"]
    Styles = ["mediterranean", "modern", "craftsman", "ranch", "colonial", "victorian"]
    Music = ["country", "hip hop", "pop", "jazz", "classical", "rock"]
    Hobbies = ["cooking", "painting", "photography", "woodworking", "gardening", "knitting"]

    all_values = {
        "Name": Names,
        "HouseStyle": Styles,
        "MusicGenre": Music,
        "Hobby": Hobbies,
    }

    # Helper to create variable key
    def var(category, house):
        return (category, house)

    # Initialize domains
    domains = {}
    for h in houses:
        domains[var("Name", h)] = set(Names)
        domains[var("HouseStyle", h)] = set(Styles)
        domains[var("MusicGenre", h)] = set(Music)
        domains[var("Hobby", h)] = set(Hobbies)

    # Utility functions
    def deep_copy_domains(dom):
        return {k: set(v) for k, v in dom.items()}

    def get_assigned(dom):
        return {k: next(iter(v)) for k, v in dom.items() if len(v) == 1}

    def houses_with_value(dom, category, value):
        return [h for h in houses if value in dom[var(category, h)]]

    def ensure_presence(dom, category, value):
        # Ensure that at least one house can still take this value
        return any(value in dom[var(category, h)] for h in houses)

    # Domain operations with propagation queue
    def set_value(dom, queue, v, value):
        if value not in dom[v]:
            return False
        if len(dom[v]) == 1 and next(iter(dom[v])) == value:
            return True
        dom[v] = {value}
        queue.append(v)
        return True

    def remove_value(dom, queue, v, value):
        if value not in dom[v]:
            return True
        if len(dom[v]) == 1 and next(iter(dom[v])) == value:
            return False
        dom[v].remove(value)
        if len(dom[v]) == 0:
            return False
        if len(dom[v]) == 1:
            queue.append(v)
        return True

    # Propagation
    def propagate(dom):
        queue = []
        # Initial global pruning from static implications:
        #  - Jazz cannot be at house 6 (needs right neighbor)
        remove_value(dom, queue, var("MusicGenre", 6), "jazz")
        #  - Eric cannot be at house 1
        remove_value(dom, queue, var("Name", 1), "Eric")
        #  - Hip hop cannot be at house 6 (must be left of knitting)
        remove_value(dom, queue, var("MusicGenre", 6), "hip hop")
        #  - Knitting cannot be at house 1
        remove_value(dom, queue, var("Hobby", 1), "knitting")

        # Fixed clues
        if not set_value(dom, queue, var("MusicGenre", 5), "rock"):
            return None
        if not set_value(dom, queue, var("MusicGenre", 1), "country"):
            return None
        if not set_value(dom, queue, var("Name", 3), "Bob"):
            return None

        # Main propagation loop
        while queue:
            (category, h) = queue.pop(0)
            value = next(iter(dom[(category, h)]))

            # All-different constraint: remove assigned value from other houses in same category
            for hh in houses:
                if hh != h:
                    if not remove_value(dom, queue, var(category, hh), value):
                        return None

            # Apply equivalences and directional constraints based on the assignment
            # 10: woodworking = victorian (biconditional)
            if category == "Hobby" and value == "woodworking":
                if not set_value(dom, queue, var("HouseStyle", h), "victorian"):
                    return None
            if category == "HouseStyle" and value == "victorian":
                if not set_value(dom, queue, var("Hobby", h), "woodworking"):
                    return None

            # 3 and 7: mediterranean = hip hop, and Carol = hip hop (biconditionals)
            if category == "HouseStyle" and value == "mediterranean":
                if not set_value(dom, queue, var("MusicGenre", h), "hip hop"):
                    return None
            if category == "MusicGenre" and value == "hip hop":
                if not set_value(dom, queue, var("HouseStyle", h), "mediterranean"):
                    return None
                if not set_value(dom, queue, var("Name", h), "Carol"):
                    return None
                # 6: hip hop left of knitting: remove knitting from houses <= h
                for hh in houses:
                    if hh <= h:
                        if not remove_value(dom, queue, var("Hobby", hh), "knitting"):
                            return None
                # Fail if hip hop at 6 (already prevented) or no place for knitting to the right
                if not any("knitting" in dom[var("Hobby", hh)] for hh in houses if hh > h):
                    return None
            if category == "Name" and value == "Carol":
                if not set_value(dom, queue, var("MusicGenre", h), "hip hop"):
                    return None

            # 8: Craftsman = Arnold (biconditional)
            if category == "Name" and value == "Arnold":
                if not set_value(dom, queue, var("HouseStyle", h), "craftsman"):
                    return None
                # 4: Two houses between Arnold and Victorian
                allowed = set()
                if h - 3 >= 1:
                    allowed.add(h - 3)
                if h + 3 <= 6:
                    allowed.add(h + 3)
                if not allowed:
                    return None
                # Remove 'victorian' from styles at houses not in allowed
                for hh in houses:
                    if hh not in allowed:
                        if not remove_value(dom, queue, var("HouseStyle", hh), "victorian"):
                            return None
                # Ensure 'victorian' still possible somewhere
                if not ensure_presence(dom, "HouseStyle", "victorian"):
                    return None
            if category == "HouseStyle" and value == "craftsman":
                if not set_value(dom, queue, var("Name", h), "Arnold"):
                    return None

            # 9 and 14: Ranch = Eric and Gardening = Eric (both biconditionals)
            if category == "Name" and value == "Eric":
                if not set_value(dom, queue, var("HouseStyle", h), "ranch"):
                    return None
                if not set_value(dom, queue, var("Hobby", h), "gardening"):
                    return None
                # 5: jazz directly left of Eric (so music at h-1 is jazz)
                if h == 1:
                    return None
                if not set_value(dom, queue, var("MusicGenre", h - 1), "jazz"):
                    return None
            if category == "HouseStyle" and value == "ranch":
                if not set_value(dom, queue, var("Name", h), "Eric"):
                    return None
            if category == "Hobby" and value == "gardening":
                if not set_value(dom, queue, var("Name", h), "Eric"):
                    return None

            # 13: Alice = photography (biconditional)
            if category == "Name" and value == "Alice":
                if not set_value(dom, queue, var("Hobby", h), "photography"):
                    return None
            if category == "Hobby" and value == "photography":
                if not set_value(dom, queue, var("Name", h), "Alice"):
                    return None

            # 5: jazz directly left of Eric (biconditional relation)
            if category == "MusicGenre" and value == "jazz":
                if h == 6:
                    return None
                if not set_value(dom, queue, var("Name", h + 1), "Eric"):
                    return None

            # 6: hip hop left of knitting - handle if knitting is assigned
            if category == "Hobby" and value == "knitting":
                # Remove hip hop from houses >= h
                for hh in houses:
                    if hh >= h:
                        if not remove_value(dom, queue, var("MusicGenre", hh), "hip hop"):
                            return None
                # Fail if knitting at 1? Alone ok but hip hop must be to left -> impossible
                if h == 1:
                    return None
                # Ensure that there is some house < h for hip hop
                if not any("hip hop" in dom[var("MusicGenre", hh)] for hh in houses if hh < h):
                    return None

            # 2 and 10: classical next to woodworking/victorian (adjacency)
            if category == "MusicGenre" and value == "classical":
                neighbors = set()
                if h - 1 >= 1:
                    neighbors.add(h - 1)
                if h + 1 <= 6:
                    neighbors.add(h + 1)
                if not neighbors:
                    return None
                # woodworking/victorian must be at neighbors
                for hh in houses:
                    if hh not in neighbors:
                        if not remove_value(dom, queue, var("Hobby", hh), "woodworking"):
                            return None
                        if not remove_value(dom, queue, var("HouseStyle", hh), "victorian"):
                            return None
                # Ensure woodworking/victorian still possible adjacent
                if not any("woodworking" in dom[var("Hobby", hh)] for hh in neighbors):
                    return None
                if not any("victorian" in dom[var("HouseStyle", hh)] for hh in neighbors):
                    return None
            if (category == "Hobby" and value == "woodworking") or (category == "HouseStyle" and value == "victorian"):
                neighbors = set()
                if h - 1 >= 1:
                    neighbors.add(h - 1)
                if h + 1 <= 6:
                    neighbors.add(h + 1)
                if not neighbors:
                    return None
                # classical must be at neighbors
                for hh in houses:
                    if hh not in neighbors:
                        if not remove_value(dom, queue, var("MusicGenre", hh), "classical"):
                            return None
                if not any("classical" in dom[var("MusicGenre", hh)] for hh in neighbors):
                    return None

            # 4: Two houses between Arnold and the Victorian house (if one side just got set by style=Victorian)
            if category == "HouseStyle" and value == "victorian":
                allowed = set()
                if h - 3 >= 1:
                    allowed.add(h - 3)
                if h + 3 <= 6:
                    allowed.add(h + 3)
                if not allowed:
                    return None
                for hh in houses:
                    if hh not in allowed:
                        if not remove_value(dom, queue, var("Name", hh), "Arnold"):
                            return None
                if not ensure_presence(dom, "Name", "Arnold"):
                    return None

            # 12: One house between painting and colonial (distance 2)
            if category == "Hobby" and value == "painting":
                allowed = set()
                if h - 2 >= 1:
                    allowed.add(h - 2)
                if h + 2 <= 6:
                    allowed.add(h + 2)
                if not allowed:
                    return None
                for hh in houses:
                    if hh not in allowed:
                        if not remove_value(dom, queue, var("HouseStyle", hh), "colonial"):
                            return None
                if not ensure_presence(dom, "HouseStyle", "colonial"):
                    return None
            if category == "HouseStyle" and value == "colonial":
                allowed = set()
                if h - 2 >= 1:
                    allowed.add(h - 2)
                if h + 2 <= 6:
                    allowed.add(h + 2)
                if not allowed:
                    return None
                for hh in houses:
                    if hh not in allowed:
                        if not remove_value(dom, queue, var("Hobby", hh), "painting"):
                            return None
                if not ensure_presence(dom, "Hobby", "painting"):
                    return None

            # Global feasibility check for each category's values to still be possible somewhere
            for cat, vals in all_values.items():
                for val in vals:
                    if not ensure_presence(dom, cat, val):
                        return None

        return dom

    # Entry propagate initial constraints
    domains = propagate(domains)
    if domains is None:
        raise RuntimeError("Initial propagation failed; no solution.")

    # MRV variable selection
    def select_unassigned_var(dom):
        candidates = [v for v in dom if len(dom[v]) > 1]
        if not candidates:
            return None
        # MRV heuristic
        candidates.sort(key=lambda x: len(dom[x]))
        return candidates[0]

    def backtrack(dom):
        # Check if solved
        if all(len(dom[v]) == 1 for v in dom):
            return dom
        var_to_assign = select_unassigned_var(dom)
        if var_to_assign is None:
            return dom
        domain_values = sorted(list(dom[var_to_assign]))
        for val in domain_values:
            new_dom = deep_copy_domains(dom)
            queue = []
            if set_value(new_dom, queue, var_to_assign, val):
                new_dom = propagate(new_dom)
                if new_dom is not None:
                    result = backtrack(new_dom)
                    if result is not None:
                        return result
        return None

    solution_domains = backtrack(domains)
    if solution_domains is None:
        raise RuntimeError("No solution found.")

    # Build output
    assigned = get_assigned(solution_domains)
    header = ["House", "Name", "HouseStyle", "MusicGenre", "Hobby"]
    rows = []
    for h in houses:
        row = [
            str(h),
            next(iter(solution_domains[var("Name", h)])),
            next(iter(solution_domains[var("HouseStyle", h)])),
            next(iter(solution_domains[var("MusicGenre", h)])),
            next(iter(solution_domains[var("Hobby", h)])),
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
